    localStorage.setItem('hash', '');

    function unhash(hash) {
        var parts = [];
        var letters = 'acdegilmnoprstuw';
        while (hash !== 7) {
            var index = hash % 37;
            hash = (hash - index) / 37;
            parts.unshift(letters[index]);
        }
        return parts.join('');
    }

    function hash(str) {
        var h = 7;
        var letters = 'acdegilmnoprstuw';
        for (var i = 0, len = str.length; i < len; i++) {
            h = (h * 37 + letters.indexOf(str[i]))
        }
        return h;
    }





