function removeTooltip() {
    document.getElementById('tooltip').remove();
}
$(function () {


    var tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));
    var tooltipList = tooltipTriggerList.map(function (tooltipTriggerEl) {
        if (document.documentElement.clientWidth <= 600) {
            tooltipTriggerEl.addEventListener("click", function () {
                event.preventDefault();
                //Create the element using the createElement method.
                var myDiv = document.createElement("div");
                myDiv.id = 'tooltip';
                myDiv.setAttribute('onclick', 'removeTooltip()');
                myDiv.style.cssText = 'z-index:99';
                myDiv.classList.add('position-fixed', 'top-0', 'end-0', 'bg-white', 'h-100', 'start-0');
                myDiv.innerHTML = '<button onclick="removeTooltip()"style="position:absolute;left:0px;background-color:#fff;color:rgb(0,0,0);"class="border">x</button>' + tooltipTriggerEl.getAttribute('data-bs-original-title');
                document.body.appendChild(myDiv);
            });

        }
        else return new bootstrap.Tooltip(tooltipTriggerEl)
    });


    if (document.documentElement.clientWidth <= 600) {

        $('#stickydrawing').hide();
        $('#test1234').hide();
        $('.stairHole input, .stairHole label').hide();
        $('div.headroom.protected').addClass('d-none');

    }


    $(document).on("click", '.mobilemenu', function () {
        $('.mobilemenu').removeClass('btn-light')

        $('.mobilemenu').addClass('btn-secondary')
        $(this).addClass('btn-light')
        $('#magnifySvg').hide();
        $('#accordionExample').hide();
        $('#site-navigation').hide();
        $('#test1234').hide();


        $('#stickydrawing').addClass('mt-5');

        if (document.querySelector('#test1234').classList.contains('zoom'))
            $('#magnify').click();

        if (document.querySelector('#stickydrawing').classList.contains('zoom'))
            $('#magnifySvg').click();

        if ($(this).attr('id') == 'mobile2d') {

            $('#stickydrawing').show();
            $('#magnifySvg').click();
        }
        else if ($(this).attr('id') == 'mobile3d') {

            $('#test1234').show();
            $('#magnify').click();
        }
        else {

            $('#site-navigation').show();
            $('#accordionExample').show();
            $('#stickydrawing').hide();
            $('#test1234').hide();
        }

    });





    $(document).on("click", '.book-a-meeting', function (event) {

        event.preventDefault();
        $('.wbtn-booking').click();
        /*.attr('style','').removeClass('zoomed').mouseout();*/

    });




    $(document).on("click", '#goinglock', function (event) {

        const current = $('#lockgoing').val();
        let newval = 0;

        if (current == 0) {
            newval = 1;

        }

        $('#goinglock').toggleClass('locked')
        $('#lockgoing').val(newval);
        urlstructure(false);
        /*.attr('style','').removeClass('zoomed').mouseout();*/

    });


    $(document).on("click", '#steplock', function (event) {

        const current = $('#lockstep').val();
        let newval = 0;

        if (current == 0) {
            newval = 1;

        }

        $('#steplock').toggleClass('locked')
        $('#lockstep').val(newval);
        urlstructure(false);
        /*.attr('style','').removeClass('zoomed').mouseout();*/

    });


    document.querySelectorAll("#collapseFour img:not(.nozoom)").forEach(img => {
        img.addEventListener("mouseover", () => { document.getElementById('drawing').style.visibility = 'hidden'; });
        img.addEventListener("mouseout",()=>{document.getElementById('drawing').style.visibility=''});new Drift(img,{sourceAttribute:'src',paneContainer:document.querySelector('#stickydrawing'),containInline:true})})});
